 if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='add'){$svc->create((int)$user['id'],$_POST['name']??'',$_POST['account_number']??'',$_POST['bank_name']??'');$success='Beneficiary added.';}elseif($action==='disable'){$svc->disable((int)$user['id'],(int)$_POST['id']);$success='Beneficiary disabled.';}}
}catch(Throwable $e){$error=$e->getMessage();}
